<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

defineProps({ documentsUsed: Number, documents: Array });
const fileInput = ref(null);
const isDragging = ref(false);
const form = useForm({ file: null });
function chooseFile(file) { if (file) form.file = file; }
function submit() { if (form.file) form.post(route('documents.store'), { forceFormData: true }); }
function formatStatus(status) { return { processed: 'Ready', pending: 'Processing', failed: 'Failed' }[status] || status; }
</script>

<template>
    <Head title="Workspace" />
    <AuthenticatedLayout>
        <div class="min-h-screen bg-[#f4f6f3] text-[#17251d]"><main class="mx-auto max-w-7xl px-5 py-10 sm:px-8 lg:py-14">
            <div class="mb-10 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p class="mb-3 text-xs font-bold uppercase tracking-[0.22em] text-[#749080]">Workspace / Overview</p><h1 class="font-serif text-4xl tracking-tight sm:text-5xl">Your file, made readable.</h1><p class="mt-3 max-w-xl text-[#627168]">Turn complex documents into data ready for action.</p></div><div class="rounded-full border border-[#d4ddd6] bg-white px-4 py-2 text-sm text-[#53635a]">Starter plan <span class="mx-2 text-[#cad5cd]">|</span> 300 docs / month</div></div>
            <section class="grid gap-5 md:grid-cols-[1.35fr_1fr]"><form @submit.prevent="submit" @dragover.prevent="isDragging = true" @dragleave.prevent="isDragging = false" @drop.prevent="isDragging = false; chooseFile($event.dataTransfer.files[0])" class="relative overflow-hidden rounded-2xl bg-[#18372b] p-7 text-white shadow-[0_18px_45px_rgba(24,55,43,.16)] sm:p-10" :class="{ 'ring-4 ring-[#d6a84f]': isDragging }"><div class="relative"><div class="mb-10 flex items-center justify-between"><span class="text-2xl font-semibold tracking-tight">New extraction</span><span class="rounded-full bg-[#d6a84f] px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-[#18372b]">Gemini 2.5</span></div><button type="button" @click="fileInput.click()" class="group flex min-h-48 w-full flex-col items-center justify-center rounded-xl border border-dashed border-[#71907e] bg-[#214635] px-5 text-center transition hover:border-[#d6a84f] hover:bg-[#28513e]"><span class="mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-[#d6a84f] text-2xl text-[#18372b]">+</span><span class="font-medium">{{ form.file ? form.file.name : 'Drop your PDF or image here' }}</span><span class="mt-2 text-sm text-[#a9c0b2]">PDF, JPG, PNG, or WEBP · up to 20 MB</span></button><input ref="fileInput" type="file" class="hidden" accept=".pdf,.jpg,.jpeg,.png,.webp" @change="chooseFile($event.target.files[0])" /><button type="submit" :disabled="!form.file || form.processing" class="mt-5 w-full rounded-lg bg-[#f3eee3] px-5 py-3.5 text-sm font-bold text-[#18372b] transition hover:bg-white disabled:cursor-not-allowed disabled:opacity-50">{{ form.processing ? 'Uploading...' : 'Extract data' }} <span class="ml-2">→</span></button><p v-if="form.errors.file" class="mt-3 text-sm text-[#ffd6c9]">{{ form.errors.file }}</p></div></form>
            <div class="rounded-2xl border border-[#dce4de] bg-white p-7 sm:p-10"><div class="flex items-start justify-between"><div><p class="text-sm text-[#718078]">Monthly usage</p><p class="mt-3 text-4xl font-semibold tracking-tight">{{ documentsUsed }} <span class="text-lg font-normal text-[#9aa79f]">/ 300</span></p></div><span class="text-2xl">◌</span></div><div class="mt-8 h-2 overflow-hidden rounded-full bg-[#e7ece8]"><div class="h-full rounded-full bg-[#d6a84f] transition-all" :style="{ width: `${Math.min((documentsUsed / 300) * 100, 100)}%` }"></div></div><p class="mt-4 text-sm text-[#718078]">{{ 300 - documentsUsed }} extractions available</p><div class="mt-10 border-t border-[#edf0ed] pt-5"><p class="text-xs font-bold uppercase tracking-widest text-[#9aa79f]">Average accuracy</p><p class="mt-2 text-2xl font-semibold">98.4%</p></div></div></section>
            <section class="mt-12"><div class="mb-4 flex items-center justify-between"><h2 class="text-xl font-semibold">Recent documents</h2><span class="text-sm text-[#87958c]">{{ documents.length }} files</span></div><div class="overflow-hidden rounded-2xl border border-[#dce4de] bg-white"><div v-if="!documents.length" class="px-6 py-12 text-center text-[#87958c]">Your processed documents will appear here.</div><Link v-for="document in documents" :key="document.id" :href="route('documents.show', document.id)" class="flex items-center justify-between border-b border-[#edf0ed] px-5 py-4 last:border-0 hover:bg-[#fafcf9] sm:px-6"><div class="flex min-w-0 items-center gap-4"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[#edf3ee] text-xs font-bold text-[#527260]">PDF</span><div class="min-w-0"><p class="truncate text-sm font-semibold">{{ document.original_filename }}</p><p class="mt-1 text-xs text-[#97a39b]">{{ new Date(document.created_at).toLocaleDateString('en-US') }}</p></div></div><span class="rounded-full px-3 py-1 text-xs font-semibold" :class="document.status === 'processed' ? 'bg-[#e5f4e8] text-[#397048]' : document.status === 'failed' ? 'bg-[#fce8e3] text-[#a34d3d]' : 'bg-[#fff3d7] text-[#967027]'">{{ formatStatus(document.status) }}</span></Link></div></section>
        </main></div>
    </AuthenticatedLayout>
</template>
